        raise SystemExit("program failed rc=%d: %s" % (p.returncode, p.stderr.decode()[:3000]))
    out = []
    for ln in p.stdout.decode("utf-8").splitlines():
        out.append(json.loads(ln))
    return out


def atom_truth(op, pat, w):
    if op == "match":
        return list(w) == list(pat)
    if op == "startswith":
        return len(w) >= len(pat) and list(w[:len(pat)]) == list(pat)
    if op == "endswith":
        return len(w) >= len(pat) and list(w[len(w) - len(pat):]) == list(pat)
    if op == "contains":
        n, m = len(w), len(pat)
        for i in range(n - m + 1):
            if list(w[i:i + m]) == list(pat):
                return True
        return False
    raise AssertionError(op)


def expr_truth(node, w):
    op = node["op"]
    if op == "true":
        return True
    if op == "false":
        return False
    if op in ("match", "startswith", "endswith", "contains"):
        return atom_truth(op, node["path"], w)
    if op == "not":
        return not expr_truth(node["arg"], w)
    if op == "and":
        return all(expr_truth(a, w) for a in node["args"])
    if op == "or":
        return any(expr_truth(a, w) for a in node["args"])
    raise AssertionError(op)


def lang_truth(req, w):
    allow = False
    drop = False
    for rule in req["rules"]:
        t = expr_truth(rule["when"], w)
        if rule["action"] == "allow":
            allow = allow or t
        else:
            drop = drop or t
    return allow and not drop


def check_request(req, out, maxlen=7):
    problems = []
    if not out.get("ok"):
        return ["expected success, got %r" % (out,)]
    dfa = out["dfa"]
    alphabet = req["services"]
    k = len(alphabet)
    accept = dfa["accept"]
    nxt = dfa["next"]
    dist = dfa["distance"]
    n = len(accept)
    if dfa["start"] != 0:
        problems.append("start != 0")
    if len(nxt) != n:
        problems.append("next rows %d != states %d" % (len(nxt), n))
    for row in nxt:
        if len(row) != k:
            problems.append("row width %d != alphabet %d" % (len(row), k))
        for t in row:
            if not (0 <= t < n):
                problems.append("bad transition %d" % t)
    # reachability
    seen = {0}
    stack = [0]
    while stack:
        s = stack.pop()
        for t in nxt[s]:
            if t not in seen:
                seen.add(t)
                stack.append(t)
    if len(seen) != n:
        problems.append("unreachable states: %d of %d" % (n - len(seen), n))
    # semantics on all words up to maxlen
    def run(w):
        s = 0
        for tok in w:
            s = nxt[s][alphabet.index(tok)]
        return s
    words = []
    for L in range(maxlen + 1):
        for tup in itertools.product(range(k), repeat=L):
            words.append([alphabet[i] for i in tup])
    for w in words:
        s = run(w)
        want = lang_truth(req, w)
        if accept[s] != want:
            problems.append("semantics wrong for %r: got %s want %s" % (w, accept[s], want))
            break
    # minimality: distinct states must be distinguished within n-1 tokens
    limit = max(n - 1, 0)
    for a in range(n):
        for b in range(a + 1, n):
            found = False
            for L in range(limit + 1):
                for tup in itertools.product(range(k), repeat=L):
                    suf = [alphabet[i] for i in tup]
                    sa, sb = a, b
                    for tok in suf:
                        sa = nxt[sa][alphabet.index(tok)]
                        sb = nxt[sb][alphabet.index(tok)]
                    if accept[sa] != accept[sb]:
                        found = True
                        break
                if found:
                    break
            if not found:
                problems.append("states %d and %d are equivalent (not minimal)" % (a, b))
                break
        else:
            continue
        break
    # canonical numbering: BFS from 0 in alphabet order
    order = []
    seen = {0}
    queue = [0]
    while queue:
        s = queue.pop(0)
        order.append(s)
        for t in nxt[s]:
            if t not in seen:
                seen.add(t)
                queue.append(t)
    if order != list(range(n)):
        problems.append("numbering is not canonical BFS: %r" % (order,))
    # distances: forward layered BFS
    inf = None
    want_dist = [None] * n
    layer = [s for s in range(n) if accept[s]]
    for s in layer:
        want_dist[s] = 0
    d = 0
    while layer:
        d += 1
        nxt_layer = []
        for s in layer:
            for t in nxt[s]:
                if want_dist[t] is None:
                    want_dist[t] = d
                    nxt_layer.append(t)
        layer = nxt_layer
    if want_dist != dist:
        problems.append("distance mismatch %r != %r" % (dist, want_dist))
    # query answers
    if len(out["queries"]) != len(req["queries"]):
        problems.append("query count mismatch")
    else:
        for q, ans in zip(req["queries"], out["queries"]):
            s = run(q)
            if ans["state"] != s or ans["allow"] != accept[s] or ans["distance"] != dist[s]:
                problems.append("query answer mismatch %r %r" % (q, ans))
    return problems


def rand_expr(rng, alphabet, depth=0):
    r = rng.random()
    if depth > 2 or r < 0.35:
        op = rng.choice(["match", "startswith", "endswith", "contains"])
        n = rng.randint(0, 3)
        path = [rng.choice(alphabet) for _ in range(n)]
        return {"op": op, "path": path}
    if r < 0.45:
        return {"op": rng.choice(["true", "false"])}
    if r < 0.6:
        return {"op": "not", "arg": rand_expr(rng, alphabet, depth + 1)}
    op = rng.choice(["and", "or"])
    n = rng.randint(0, 3)
    return {"op": op, "args": [rand_expr(rng, alphabet, depth + 1) for _ in range(n)]}


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    reqs = []
    for _ in range(count):
        alphabet = rng.sample(["a", "b", "c", "ab", "x y", "\u00e9"], rng.randint(0, 3))
        rules = []
        for _ in range(rng.randint(0, 4)):
            rules.append({"action": rng.choice(["allow", "drop"]),
                          "when": rand_expr(rng, alphabet)})
        queries = []
        for _ in range(rng.randint(0, 4)):
            queries.append([rng.choice(alphabet) for _ in range(rng.randint(0, 4))]
                            if alphabet else [])
        reqs.append({"services": alphabet, "rules": rules, "queries": queries})
    lines = [json.dumps(r, ensure_ascii=False) for r in reqs]
    outs = run(lines)
    assert len(outs) == len(reqs), (len(outs), len(reqs))
    bad = 0
    for req, out in zip(reqs, outs):
        probs = check_request(req, out)
        if probs:
